from pathlib import Path
import json
out=Path(__file__).resolve().parents[1]
before=json.loads((out/'visual-diff/before-metrics.json').read_text())
after=json.loads((out/'visual-diff/final-metrics.json').read_text())
labels={'whole':'整页','header':'顶部导航','hero':'左侧主文案','apps':'三块应用屏幕','application_platform':'应用层平台','intelligence':'智能角色层','data_foundation':'业务对象与城市','earth':'地球与地平线','sidebar':'右侧说明'}
rows=[]
for key,label in labels.items():
 a,b=before['regions'][key],after['regions'][key]
 reduction=(1-b['mae_rgb']/a['mae_rgb'])*100
 rows.append(f'<tr><th><button data-region="{key}">{label} ↗</button></th><td>{a["mae_rgb"]:.2f}</td><td>{b["mae_rgb"]:.2f}</td><td class="gain">↓ {reduction:.1f}%</td><td>{a["ssim_gray"]:.3f} → {b["ssim_gray"]:.3f}</td></tr>')
reduction=(1-after['regions']['whole']['mae_rgb']/before['regions']['whole']['mae_rgb'])*100
data=json.dumps({'before':before,'after':after,'labels':labels},ensure_ascii=False)
html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WinBrain · 原图差异对照</title><style>
*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#0c121b;color:#e0eaf7;font:14px/1.7 -apple-system,BlinkMacSystemFont,"PingFang SC",Arial,sans-serif}a{color:inherit;text-decoration:none}button,select{font:inherit;color:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid #89d7ec;outline-offset:4px}header{padding:22px 4vw;display:flex;justify-content:space-between;border-bottom:1px solid #293545}header strong{font-size:20px}nav{display:flex;gap:25px;font-size:12px;color:#a4bbd5}main{max-width:1460px;margin:auto;padding:40px 3vw 70px}.intro{display:flex;justify-content:space-between;gap:30px;align-items:end;margin-bottom:28px}.eyebrow{color:#8badca;font-size:10px;letter-spacing:2px}h1{font-weight:500;font-size:32px;letter-spacing:-1px;margin:8px 0 12px}p{color:#9fb1c7;margin:8px 0}.score{flex-shrink:0;text-align:right}.score strong{font-size:42px;font-weight:400;color:#93d3c1}.score small{display:block;font-size:11px;color:#97aabf}.toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:9px;padding:13px 0}button,select{border:1px solid #3a4b62;background:#192638;border-radius:6px;padding:8px 12px;font-size:12px}button[aria-pressed="true"]{color:#d5f8ff;border-color:#7daec9;background:#254157}.toolbar label{font-size:12px;color:#9db3ce}.toolbar select{margin-left:7px}.toolbar .native{margin-left:auto}.viewer-wrap{overflow:auto;border:1px solid #35495f;border-radius:9px;background:#060a10}.viewer{display:block;width:100%;height:auto;touch-action:pan-y}.viewer.native{width:1536px;max-width:none}.split-line{stroke:#d0f4ff;stroke-width:1.5;vector-effect:non-scaling-stroke;pointer-events:none}.range{display:flex;align-items:center;gap:16px;padding:12px 0;color:#9db3cc;font-size:12px}.range input{width:100%;accent-color:#9bdbdc}.range span{white-space:nowrap}.caption{font-size:12px;min-height:22px;margin:0 0 30px}h2{font-size:19px;font-weight:500;margin:32px 0 12px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:12px 16px;text-align:right;border-bottom:1px solid #263448;font-variant-numeric:tabular-nums}th:first-child{text-align:left}thead{color:#88a2bf;font-size:11px}tbody th{font-weight:400}tbody th button{background:none;padding:0;border:0;color:#c4d7ed}.gain{color:#9bd4c5}.notes{display:grid;grid-template-columns:1fr 1fr;gap:42px;margin-top:8px}.notes p{font-size:13px;line-height:1.9}.method{margin-top:30px;padding:19px 23px;border:1px solid #2d3c50;border-radius:8px;font-size:12px;color:#94a8c1}.method strong{color:#cadbed;font-weight:500}.method a{text-decoration:underline;text-underline-offset:3px}.downloads{display:flex;gap:24px;flex-wrap:wrap;margin-top:20px;font-size:12px;color:#9bbfe5}footer{margin-top:35px;color:#748aa6;font-size:11px}@media(max-width:720px){header{padding:18px 20px}nav{gap:14px}main{padding:28px 20px}h1{font-size:26px}.intro{display:block}.score{text-align:left;margin-top:15px}.score strong{font-size:31px}.notes{grid-template-columns:1fr;gap:4px}.toolbar .native{margin-left:0}th,td{padding:10px 9px}.intro p{font-size:12px}}
</style></head><body><header><strong>WinBrain <span style="font-size:12px;font-weight:400;color:#8da3bd">/ 视觉对照</span></strong><nav><a href="index.html">三维首页 ↗</a><a href="studio.html">组件编辑器 ↗</a><a href="catalog.html">资产库 ↗</a></nav></header><main><div class="intro"><div><span class="eyebrow">REFERENCE → CODE → OPENCV</span><h1>把差异放在同一张画布上。</h1><p>原图与页面截图均为 1536 × 1024。拖动分界线检查位置，切换热图查看仍有差异的地方。</p></div><div class="score"><strong>↓ __REDUCTION__%</strong><small>整页平均像素差异 · 相对本轮修改前</small></div></div>
<div class="toolbar"><button data-mode="wipe" aria-pressed="true">拖动对照</button><button data-mode="heat" aria-pressed="false">差异热图</button><button data-mode="edges" aria-pressed="false">轮廓对照</button><button data-mode="overlay" aria-pressed="false">半透明叠图</button><label>截图<select id="version"><option value="final">修改后</option><option value="before">修改前</option></select></label><label>区域<select id="region">__OPTIONS__</select></label><button class="native" id="native" aria-pressed="false">原始像素 1:1</button></div>
<div class="viewer-wrap"><svg class="viewer" id="viewer" viewBox="0 0 1536 1024" role="img" aria-label="原始设计与代码页面的交互对照"><defs><clipPath id="clip"><rect id="cliprect" x="768" y="0" width="1536" height="1024"/></clipPath></defs><image href="assets/reference.png" width="1536" height="1024"/><image id="capture" href="visual-diff/final.png" width="1536" height="1024" clip-path="url(#clip)"/><image id="analysis" href="visual-diff/final-heatmap.png" width="1536" height="1024" visibility="hidden"/><line id="split" class="split-line" x1="768" x2="768" y1="0" y2="1024"/></svg></div><div class="range"><span>原始设计</span><input id="wipe" type="range" min="0" max="100" value="50" step=".1" aria-label="原图与截图分界位置"><span id="version-label">修改后</span></div><p class="caption" id="caption" aria-live="polite">左边为原图，右边为修改后的代码页面。拖动滑杆，或直接在图上拖动。</p>
<h2>每个区域都单独计算</h2><p style="font-size:12px">点击区域名称可以放大查看。像素差异越低越好；SSIM 越高表示结构越接近，它不是“还原百分比”。</p><div class="table-wrap"><table><thead><tr><th>区域</th><th>修改前差异</th><th>修改后差异</th><th>差异降低</th><th>结构相似度 SSIM</th></tr></thead><tbody>__ROWS__</tbody></table></div>
<div class="notes"><div><h2>这次修了什么</h2><p>缩小并倾斜玻璃平台，调整后侧深度、反光和透明度；修正平台数字与标题的垂直对齐，以及角色旁说明的位置。</p><p>提高三块应用屏幕的亮度，增加底部反射；调整人物颜色和躯干；补充业务底座的金属顶面、绿地和树木；抬高地球弧顶并重做大气柔光。</p></div><div><h2>仍有可见差异</h2><p>人物轮廓、建筑排列、玻璃折射和高光还没有达到逐像素一致；原图中的随机细节无法只靠一张图完整反推出三维场景。</p><p>地球云层、陆地和灯点仍是程序生成的近似；文字边缘也受浏览器字体渲染影响。热图的亮区保留了这些差异，没有用原图贴片覆盖页面。</p></div></div>
<div class="method"><strong>怎样比较</strong><br>OpenCV 4.12.0，Chromium 固定参考镜头，设备像素比例 1，暂停动画。MAE 计算原始 RGB 通道绝对差的均值（0–255）；SSIM 使用灰度图、11 × 11 高斯窗、σ 1.5。热图显示 σ 3 模糊后的 RGB 绝对差，统一放大 3 倍：越亮，差异越大。轮廓图采用 Canny 50 / 130，原图青色、截图橙色、重合为白色。没有自动移动、拉伸、遮罩或配准图片；指标由完整原始像素计算。表中区域存在重叠，不能相加。<br><a href="visual-diff/README.md">复现步骤与限制</a> · <a href="visual-diff/final-metrics.json">最终测量 JSON</a> · <a href="visual-diff/iterations.json">六轮修改记录</a></div>
<div class="downloads"><a href="visual-diff/final.png" download>最终截图 ↓</a><a href="visual-diff/before.png" download>修改前截图 ↓</a><a href="visual-diff/final-heatmap.png" download>差异热图 ↓</a><a href="visual-diff/final-edges.png" download>轮廓图 ↓</a><a href="https://github.com/liush2yuxjtu/winbrain-3d-component-studio/archive/refs/heads/main.zip" download>完整可运行项目 ↓</a></div><footer>所有模型仍可独立旋转、编辑和替换。此页用于查看测量结果，不会修改你的布局。</footer></main><script>
const report=__DATA__;
const $=s=>document.querySelector(s),viewer=$('#viewer');let mode='wipe',rect=[0,0,1536,1024],drag=false;
function render(){const version=$('#version').value;$('#capture').setAttribute('href','visual-diff/'+version+'.png');$('#version-label').textContent=version==='final'?'修改后':'修改前';const [x,y,w,h]=rect,f=+$('#wipe').value/100,split=x+w*f;viewer.setAttribute('viewBox',rect.join(' '));viewer.style.aspectRatio=w+'/'+h;viewer.style.width=viewer.classList.contains('native')?w+'px':'';$('#cliprect').setAttribute('x',split);$('#cliprect').setAttribute('width',1536-split);for(const a of ['x1','x2'])$('#split').setAttribute(a,split);$('#split').setAttribute('visibility',mode==='wipe'?'visible':'hidden');$('#analysis').setAttribute('visibility',mode==='wipe'?'hidden':'visible');$('#analysis').setAttribute('href','visual-diff/'+version+'-'+({heat:'heatmap',edges:'edges',overlay:'overlay'}[mode]||'heatmap')+'.png');$('.range').style.visibility=mode==='wipe'?'visible':'hidden';$('#caption').textContent={wipe:'左边为原图，右边为'+(version==='final'?'修改后':'修改前')+'的代码页面。拖动滑杆，或直接在图上拖动。',heat:'暗色表示接近，橙黄和白色表示较大的差异。修改前后使用相同色标。',edges:'青色：原图轮廓；橙色：截图轮廓；白色：两者重合。',overlay:'原图与截图各占 50% 透明度。双影能帮助识别位置和轮廓偏差。'}[mode];document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render();});$('#version').onchange=render;$('#wipe').oninput=render;
$('#region').onchange=()=>{rect=report.after.regions[$('#region').value].rect;render();};document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>{$('#region').value=b.dataset.region;$('#region').onchange();viewer.scrollIntoView({behavior:'smooth',block:'center'});});
$('#native').onclick=()=>{viewer.classList.toggle('native');$('#native').setAttribute('aria-pressed',String(viewer.classList.contains('native')));if(viewer.classList.contains('native'))viewer.style.width=rect[2]+'px';else viewer.style.width='';};
const move=e=>{if(mode!=='wipe')return;const b=viewer.getBoundingClientRect();$('#wipe').value=Math.max(0,Math.min(100,100*(e.clientX-b.left)/b.width));render();};viewer.onpointerdown=e=>{if(mode!=='wipe')return;drag=true;viewer.setPointerCapture(e.pointerId);move(e);};viewer.onpointermove=e=>{if(drag)move(e);};viewer.onpointerup=viewer.onpointercancel=()=>drag=false;render();
</script></body></html>'''
html=html.replace('__REDUCTION__',f'{reduction:.1f}').replace('__ROWS__',''.join(rows)).replace('__OPTIONS__',''.join(f'<option value="{key}">{value}</option>' for key,value in labels.items())).replace('__DATA__',data)
(out/'comparison.html').write_text(html)
print('Built comparison.html')
